export const EXERCISE_MAP = new Map<string, Exercise>(
  EXERCISE_LIBRARY.map((e) => [e.id, e])
);

export const findExercise = (idOrName?: string): Exercise | undefined => {
  if (!idOrName) return undefined;
  const direct = EXERCISE_MAP.get(idOrName);
  if (direct) return direct;
  const lower = idOrName.toLowerCase().trim();
  return EXERCISE_LIBRARY.find((e) => e.id.toLowerCase() === lower || e.name.toLowerCase() === lower);
};
